{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx experimental icon add",
    "description": "[experimental] Register one icon you chose from a library in your icon set",
    "usage": "astryx experimental icon add [options] [export]",
    "options": [
      {
        "flags": "--from <module>",
        "description": "The module the icon is exported from: a package, a subpath, or a ./ path to a file inside this package"
      },
      {
        "flags": "--definition <name>",
        "description": "Map the icon to this icon definition"
      },
      {
        "flags": "--new-definition <name>",
        "description": "Add your set's own definition, named in camelCase (aiHelper) or kebab-case (ai-helper), then map the icon to it; needs --description and --words"
      },
      {
        "flags": "--description <text>",
        "description": "With --new-definition: what the icon is for"
      },
      {
        "flags": "--words <list>",
        "description": "With --new-definition: comma-separated words people search for"
      },
      {
        "flags": "--default",
        "description": "The module's default export is the icon; your set's module must re-export it under <export>"
      },
      {
        "flags": "--variant <name>",
        "description": "Add the export as this variant of an existing icon: one of the set's declared variants, such as solid"
      },
      {
        "flags": "--all",
        "description": "With --variant and --from, and no export: add that variant for every icon whose id the module exports, in one run"
      },
      {
        "flags": "--id <id>",
        "description": "The icon's id, instead of the one its name gives"
      },
      {
        "flags": "--set <name>",
        "description": "The set to edit, when the package ships several"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
